\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\pagestyle{empty}

% --- Color theme (World Bank-ish: blues/teals + warm accent) ---
\definecolor{primary}{HTML}{0B3D91}      % deep institutional blue
\definecolor{secondary}{HTML}{0F766E}    % teal
\definecolor{accent}{HTML}{D97706}       % amber
\definecolor{bgposter}{HTML}{F4F8FF}     % cool tinted background
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{374151}

% Card tints (not pure white)
\definecolor{redbg}{HTML}{F0FDFA}        % teal-tinted
\definecolor{bluebg}{HTML}{F0F7FF}       % blue-tinted
\definecolor{darkbg}{HTML}{FFF7ED}       % warm-tinted
\definecolor{redtitlebg}{HTML}{E6FFFB}
\definecolor{bluetitlebg}{HTML}{E8F2FF}
\definecolor{darktitlebg}{HTML}{FFF0DA}
\definecolor{stathighlight}{HTML}{FFF4D6} % warm highlight for key stats

\pagecolor{bgposter}
\color{textdark}

% Lists
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% Figure macro (kept for consistency)
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{20}{24}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% Card system (left accent stripe)
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!45},
    valign=top, drop shadow={opacity=0.16},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!45},
    valign=top, drop shadow={opacity=0.16},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accent!110!black},
    coltitle=accent!110!black, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!55},
    valign=top, drop shadow={opacity=0.16},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!14!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

% Small helper for metric cards
\newcommand{\metric}[3]{%
  \fcolorbox{primary!35}{stathighlight}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{48}{56}\selectfont\bfseries\color{primary} #1}\\[2pt]
    {\fontsize{18}{22}\selectfont\color{textdark} #2}\\[2pt]
    {\fontsize{14}{18}\selectfont\color{textgray} #3}\vspace{6pt}%
  }}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ===================== TITLE BAR =====================
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=26pt, right=26pt, top=12pt, bottom=10pt,
  halign=left, valign=center,
  drop shadow={opacity=0.28}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{48}{56}\selectfont\bfseries Global Economic Prospects: Resilience Amid Uncertainty}\\[6pt]
  {\fontsize{18}{22}\selectfont\color{white!85}Strong recovery since 2020, but vulnerable economies lag as trade tensions and policy uncertainty cloud the outlook.}
  \hfill{\fontsize{14}{18}\selectfont\color{white!70}World Bank \textit{Global Economic Prospects} (report distillation)}
}

% ===================== METRICS BAND =====================
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=10pt, bottom=10pt,
  valign=center, borderline south={3pt}{0pt}{primary!35}
]{name=stats, column=1, span=2, between=row3 and row6}{
  \centering
  \begin{minipage}[c]{0.32\linewidth}\centering
    \metric{Strongest}{Recovery in 6 decades}{Post-2020 rebound}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \metric{1.2\,billion}{Youth entering working age}{Next decade}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{accent!55}{stathighlight}{\parbox{0.94\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{52}\selectfont\bfseries\color{accent!110!black}Risks rising}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark}Trade tensions \& tariffs}\\[2pt]
      {\fontsize{14}{18}\selectfont\color{textgray}Policy uncertainty}\vspace{6pt}%
    }}
  \end{minipage}
}

% ===================== RECOVERY OVERVIEW =====================
\posterbox[bluecard, title={A Historic Recovery — But Uneven}]
{name=recovery, column=1, between=row6 and row11}{
  \fontsize{16}{22}\selectfont
  \begin{itemize}
    \item Faster-than-expected growth capped the post-2020 rebound.
    \item Headline resilience masks widening divergence across countries.
    \item Vulnerable emerging market and developing economies (EMDEs) lag.
    \item Near-term growth is projected to edge down as inventory cycles turn.
  \end{itemize}

  \vspace{4pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \vspace{4pt}\fontsize{15}{20}\selectfont
    \textbf{Key message:} Resilience is real, but uneven—policy choices determine whether the recovery broadens or fragments.\vspace{4pt}
  }}
}

% ===================== RISKS (HEAVY WEIGHT) =====================
\posterbox[highlightcard, title={Risks to the Outlook (Policy-Relevant)}]
{name=risks, column=2, between=row6 and row13}{
  \fontsize{16}{22}\selectfont
  \begin{itemize}
    \item \textbf{Trade tensions:} tariff escalation \& retaliation \ $\to$ supply-chain disruption, weaker investment.
    \item \textbf{Tariff effects:} front-loading fades \ $\to$ demand softens and margins compress.
    \item \textbf{Financial volatility:} sentiment shocks \ $\to$ tighter financing, especially for EMDEs.
    \item \textbf{Inventory correction:} stock drawdowns \ $\to$ near-term growth drag.
    \item \textbf{Climate shocks:} extreme weather \ $\to$ agricultural and infrastructure losses.
  \end{itemize}

  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \vspace{4pt}\fontsize{15}{20}\selectfont
    \textbf{Takeaway:} The outlook is most sensitive to trade-policy escalation and confidence-driven tightening in financial conditions.\vspace{4pt}
  }}
}

% ===================== POLICY ACTIONS =====================
\posterbox[redcard, title={Policy Actions for Sustained Growth}]
{name=policy, column=1, between=row11 and row16}{
  \fontsize{15}{20}\selectfont
  \renewcommand{\arraystretch}{1.35}
  \setlength{\tabcolsep}{8pt}
  \begin{tabular}{p{0.46\linewidth} p{0.46\linewidth}}
    \rowcolor{secondary!15} \textbf{Global action} & \textbf{Domestic action}\\
    Improve multilateral trade environment & Diversify partners and products\\
    Ease external financing constraints for EMDEs & Strengthen macro policy frameworks\\
    Scale climate risk mitigation and adaptation & Invest in resilient infrastructure\\
    Catalyze private capital flows & Remove bottlenecks to business entry\\
    Support cross-border labor mobility & Build skills and labor-market flexibility\\
  \end{tabular}

  \vspace{6pt}
  \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
    \vspace{4pt}\fontsize{14}{18}\selectfont
    \textbf{Design principle:} Pair global coordination with domestic reforms to convert resilience into inclusive job creation.\vspace{4pt}
  }}
}

% ===================== 2030 PRIORITIES =====================
\posterbox[darkcard, title={World Bank 2030 Strategic Priorities (Targets)}]
{name=targets, column=2, between=row13 and row18}{
  \fontsize{15}{20}\selectfont
  \renewcommand{\arraystretch}{1.35}
  \setlength{\tabcolsep}{8pt}
  \begin{tabular}{p{0.40\linewidth} p{0.52\linewidth}}
    \rowcolor{accent!18} \textbf{Initiative} & \textbf{2030 target}\\
    Health services & \textbf{1.5B people} served\\
    Mission 300 (SSA electricity) & \textbf{300M people} access\\
    AgriConnect & \textbf{300M farmers} up the value chain\\
    Capital support & \textbf{80M women} and women-led businesses gain capital access\\
    Water Forward & \textbf{1B+ people} improved water security; \textbf{400M} WBG commitment\\
  \end{tabular}

  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \vspace{4pt}\fontsize{14}{18}\selectfont
    \textbf{Jobs context:} \textbf{1.2B} youth enter working age in the next decade—scale and productivity matter.\vspace{4pt}
  }}
}

% ===================== RESEARCH THEMES + FOOTER =====================
\posterbox[bluecard, title={Key Research Themes in Recent Issues (Evidence Base)}]
{name=themes, column=1, span=2, between=row16 and bottom}{
  \fontsize{15}{20}\selectfont
  \begin{minipage}[t]{0.64\linewidth}
    \begin{itemize}
      \item Fiscal policy: rebuilding fiscal space; small states.
      \item Trade costs \& supply chains: causes/remedies; value-chain disruptions.
      \item Commodity markets: price cycles; energy shocks.
      \item Financial spillovers \& pandemic economics: debt buildup; inequality.
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.32\linewidth}
    \vspace{2pt}
    \colorbox{primary!18}{\parbox{0.94\linewidth}{%
      \vspace{6pt}\centering
      {\fontsize{16}{20}\selectfont\bfseries Source materials}\\[4pt]
      {\fontsize{12}{16}\selectfont\color{textgray}World Bank \textit{Global Economic Prospects} series}\\[6pt]
      {\fontsize{12}{16}\selectfont\color{textgray}Poster: data-forward distillation}\\[6pt]
      {\fontsize{12}{16}\selectfont\color{textgray}Scan/code link: (add QR here)}\\[6pt]
    }}
  \end{minipage}
}

\end{tcbposter}
\end{document}
EOF

